        /**@type {HTMLInputElement}*/
        // @ts-ignore
        const emailAddress = document.getElementById('emailAddress');
        const submitEmail = document.getElementById('submitEmail');

        /**@type {HTMLSelectElement}*/
        // @ts-ignore
        const customerSegmentSelect = document.getElementById('customerSegment');

        /**@type {HTMLInputElement}*/
        // @ts-ignore
        const customPriceRange = document.getElementById('customPriceRange');
        /**@type {NodeListOf<HTMLElement>}*/
        // @ts-ignore
        const customPriceTextNodes = document.querySelectorAll('.customPriceText');
        const customPackageButton = document.getElementById('customPackageButton');
        const primaryPackageButtons = [
            {package:{el:document.getElementById('leadDriverBtn'),name:'Lead Driver'}},
            {package:{el:document.getElementById('awarenessDriverBtn'),name:'Awareness Driver'}},
            {package:{el:document.getElementById('premierDriverBtn'),name:'Premier Driver'}}
        ];

        /*

             border-width: 3px 3px 3px 3px; 
             border-color: #2563eb; 
             border-style: solid;
                box-shadow: 0 0 5px 0 rgb(0 0 0 / 17%);
        */

        //Use Forms for validation
        /**@type {HTMLFormElement}*/
        // @ts-ignore
        const emailForm = document.getElementById('emailForm');
        /**
         * @type {{el:HTMLInputElement,type:string}[]}
         */
         const customPlanOptions = [
            //@ts-ignore
            {el:document.getElementById('customPaidSocialAds'),type:"social"},
            //@ts-ignore
            {el:document.getElementById('customPaidDisplayAds'),type:"display"},
            //@ts-ignore
            {el:document.getElementById('customPaidSearchAds'),type:"search"}
       ];
        const campaignDetails = {
            email:()=>emailAddress.value,
            customerSegment:()=>customerSegmentSelect.value,
            selectedPackage:{
                name:'',
                customSelected:false,
                custom:{
                    ad:{
                        display:true,
                        search:false,
                        social:false
                    },
                    price:1000
                }
            }
        };

        /**
         * 
         * @param {string} selectedPackage
         */
        async function submitCampaign(selectedPackage){
            if(emailForm.checkValidity()){
                campaignDetails.selectedPackage.name = selectedPackage;
                if(selectedPackage == 'Custom')campaignDetails.selectedPackage.customSelected = true;
                const redirectPage = document.getElementById('redirectPage');

                const request = await fetch('/contact',{
                    method:"POST",
                    body:JSON.stringify({
                        email:campaignDetails.email(),
                        customerSegment:campaignDetails.customerSegment(),
                        packageDetails:campaignDetails.selectedPackage,
                        url:window.location.href
                    },),
                    headers:{
                        'Content-Type':'application/json'
                    }
                });

                const response = await request.json();

                console.log(response);

                //call server and redirect
                //@ts-ignore
                window.location.href = redirectPage.dataset.href;

            }else{
                emailForm.requestSubmit();
            }

        }

        primaryPackageButtons.forEach((pkg)=>{
            //@ts-ignore
            pkg.package.el.addEventListener('click',async ()=>{
                await submitCampaign(pkg.package.name);
            });
        });

        function countOptions(){
            let count = 0;
            customPlanOptions.forEach((val)=>{
                if(val.el.checked){
                    count ++;          
                }
            });
            return count;
        }

        /**
         * 
         * @param {string} value
         */
        function updateCustomPriceValues(value){
            campaignDetails.selectedPackage.custom.price = Number(value);
            customPriceTextNodes.forEach((node)=>{
                node.innerText = `$${Number(value).toLocaleString()}`;
            });
        }
        customPriceRange.addEventListener('change',()=>{
            updateCustomPriceValues(customPriceRange.value);

            const count = countOptions();

            if(Number(customPriceRange.value) < (count * 1000)){
                customPriceRange.value = `${count*1000}`;
                updateCustomPriceValues(`${count*1000}`);
                alert(`You have to have a minumum of $${(count*1000).toLocaleString()} budget because you have selected ${count} media channels`);

            }
        });

        //@ts-ignore
        emailForm.addEventListener('submit',(ev)=>{
            ev.preventDefault();
            //@ts-ignore
            document.getElementById('step2').scrollIntoView();
        });

        //@ts-ignore
        submitEmail.addEventListener('click',()=>{
            if(emailForm.checkValidity()){
                //@ts-ignore
                document.getElementById('step2').scrollIntoView();


            }else{
                emailForm.requestSubmit();
                //alert('Please enter a valid email address.');
            }
        });

        //console.log(customerSegmentSelect.value);
        let previousSelectedSegment = customerSegmentSelect.value;
        customerSegmentSelect.addEventListener('change',()=>{
            //selectedSegment
            //find id
            //@ts-ignore
            document.getElementById(`${previousSelectedSegment}Option`).classList.remove('selectedSegment');
            previousSelectedSegment = customerSegmentSelect.value;
            //@ts-ignore
            document.getElementById(`${customerSegmentSelect.value}Option`).classList.add('selectedSegment');

            //@ts-ignore
            document.getElementById('step3').scrollIntoView();

        });

        [...customerSegmentSelect.options].forEach((opt)=>{

            const cardSegment = document.getElementById(`${opt.value}Option`);

            //@ts-ignore
            cardSegment.addEventListener('click',()=>{
                //@ts-ignore
                document.getElementById(`${previousSelectedSegment}Option`).classList.remove('selectedSegment');
                //@ts-ignore
                previousSelectedSegment = cardSegment.id.replace('Option','');

                customerSegmentSelect.value = previousSelectedSegment;

                //@ts-ignore
                document.getElementById(cardSegment.id).classList.add('selectedSegment');

                //@ts-ignore
                document.getElementById('step3').scrollIntoView();
            })
        })



        customPlanOptions.forEach((opt)=>{
            opt.el.addEventListener('click',()=>{
                const count = countOptions();
                customPlanOptions.forEach((val)=>{
                    //@ts-ignore
                    campaignDetails.selectedPackage.custom.ad[`${val.type}`] = val.el.checked;
                });
                const customPriceRangeVal = Number(customPriceRange.value);
                if(customPriceRangeVal <= 3000 && count > 0){
                    customPriceRange.value = `${count*1000}`;
                    updateCustomPriceValues(`${count*1000}`);
                }
                if(count <= 0){
                    alert('Please select at least one media channel before submitting your campaign.');
                }
            })
        })

       //@ts-ignore
       customPackageButton.addEventListener('click',async ()=>{
            const count = countOptions();
            customPlanOptions.forEach((val)=>{
                //@ts-ignore
                campaignDetails.selectedPackage.custom.ad[`${val.type}`] = val.el.checked;
            });
            if(count < 1){
                alert('Please select at least one media channel before submitting your campaign.');
            }else{
                campaignDetails.selectedPackage.customSelected = true;
                await submitCampaign('Custom');
            }

       });



        //@ts-ignore
        window.cTest = campaignDetails;



